  const pulse2=Math.sin(dist*0.12-t*2.5+1)*Math.exp(-dist*0.008)*0.3;
  const moire=Math.sin(sx*0.2)*Math.sin(sy*0.2)+Math.sin((sx+sy)*0.14+t)*Math.sin((sx-sy)*0.14-t*0.7);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+moire*0.3)*1.5)*0.3;
  const feed=act-inh*0.7+bg*0.3+spiral+pulse1+pulse2;
  const reaction=Math.tanh(feed*2.2),reaction2=Math.tanh(feed*1.5+reaction*0.3-0.2);
  const blend=reaction*0.5+reaction2*0.25+cell*0.25,v=blend*0.5+0.5;
  const pal=[[5,12,45],[10,35,85],[12,65,115],[18,105,135],[35,150,140],[120,175,100],[200,185,65],[220,140,55],[200,85,65],[160,45,75],[90,25,60],[40,15,50],[5,12,45]];
